@startuml

class Boeing {
  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

class Airplane {
  + Name : string
}

Boeing "1" -- "*" Contract : manages
Boeing "1" -- "*" Airplane : builds
Contract "1" -- "1..*" Acquisition : consists of
Acquisition "1" -- "1" Airplane : involves
Contract "0..*" -- "1..*" Employee : managed by
Airline "0..*" -- "0..1" Airline : is related to
Airline "0..*" -- "0..*" Contract : signs

@enduml

